const parts = cmdLine.split(/s+/).filter(Boolean);

let command = (parts[0] || 'help').toLowerCase();

// Command aliases
const commandAlias = {
  price: 'stock'
};

command = commandAlias[command] || command;

const args = parts.slice(1);

const alias = {
  infosys: 'INFY',
  infy: 'INFY',
  tcs: 'TCS',
  reliance: 'RELIANCE',
  hdfcbank: 'HDFCBANK',
  hdfc: 'HDFCBANK',
  icicibank: 'ICICIBANK',
  icici: 'ICICIBANK',
  sbi: 'SBIN',
