};

function norm(sym) {
  if (!sym) return null;

  const s = sym
    .toUpperCase()
    .replace(/.NS$/, '');

  return alias[s.toLowerCase()] || s;
}

function toYahoo(sym) {
  const s = norm(sym);
  return s ? s + '.NS' : null;
}

