function num(v){
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function fpct(p){
  if(p==null || isNaN(p)) return '—';
  return (p>=0?'+':'') + Number(p).toFixed(2) + '%';
}

function arrow(p){
  if(p==null || isNaN(p)) return '⚪';
  return p>=0 ? '🟢' : '🔴';
}

function inr(n){
  if(n==null || isNaN(n)) return '—';
  return '₹' + Number(n).toLocaleString('en-IN',{
    maximumFractionDigits:2
  });
}

function inr0(n){
  if(n==null || isNaN(n)) return '—';
  return '₹' + Math.round(Number(n)).toLocaleString('en-IN');
}

function istNow(){
  try{
    return DateTime.now()
      .setZone('Asia/Kolkata')
      .toFormat('hh:mm a') + ' IST';
  }catch(e){
    return new Date().toISOString();
  }
}

function marketStatus(){
  try{
    const n = DateTime.now().setZone('Asia/Kolkata');
    const wd = n.weekday;
    const mins = n.hour * 60 + n.minute;

    const open =
      wd >= 1 &&
      wd <= 5 &&
      mins >= 555 &&
      mins <= 930;

    return open
      ? '🟢 Market Open'
      : '🔴 Market Closed';

  }catch(e){
    return '';
  }
}

function parseChart(resp){
  try{
    const r =
      resp &&
      resp.chart &&
      resp.chart.result &&
      resp.chart.result[0];

    if(!r) return null;

    const m = r.meta || {};

    const price = num(m.regularMarketPrice);

    let prevClose = num(m.chartPreviousClose);

    if(prevClose == null){
      prevClose = num(m.previousClose);
    }

    const ts = r.timestamp || [];

    const q =
      r.indicators &&
      r.indicators.quote &&
      r.indicators.quote[0];

    const closes = (q && q.close) || [];

    const series = [];

    for(let i=0; i<ts.length; i++){
      const c = closes[i];

      if(typeof c === 'number'){
        series.push({
          t: ts[i] * 1000,
          c: c
        });
      }
    }

    const last =
      price != null
        ? price
        : (series.length
            ? series[series.length - 1].c
            : null);

    function perf(days){
      if(last == null || !series.length) return null;

      const target =
        Date.now() - days * 86400000;

      let chosen = null;

      for(const p of series){
        if(p.t <= target){
          chosen = p;
        }else{
          break;
        }
      }

      if(!chosen){
        chosen = series[0];
      }

      if(
        !chosen ||
        chosen.c == null ||
        chosen.c === 0
      ){
        return null;
      }

      return ((last - chosen.c) / chosen.c) * 100;
    }

    const change =
      (last != null && prevClose != null)
        ? (last - prevClose)
        : null;

    const changePct =
      (change != null && prevClose)
        ? (change / prevClose) * 100
        : null;

    return {
      symbol: m.symbol || null,
      currency: m.currency || null,
      price: last,
      prevClose: prevClose,
      change: change,
      changePct: changePct,
      high52: num(m.fiftyTwoWeekHigh),
      low52: num(m.fiftyTwoWeekLow),
      volume: num(m.regularMarketVolume),
      exchange:
        m.fullExchangeName ||
        m.exchangeName ||
        null,
      w1: perf(7),
      m1: perf(30),
      m3: perf(91),
      y1: perf(365)
    };

  }catch(e){
    return null;
  }
}

